import { Component, EventEmitter, Input, Output } from '@angular/core';
import { BillingRecord } from '../../models/billing.model';

@Component({
  selector: 'app-billing-table',
  templateUrl: './billing-table.component.html',
  styleUrls: ['./billing-table.component.css']
})
export class BillingTableComponent {
  @Input() records: BillingRecord[] = [];
  @Input() selectedIds = new Set<number>();
  @Output() selectedIdsChange = new EventEmitter<Set<number>>();
  @Output() action = new EventEmitter<{ type: string; record: BillingRecord }>();
  openMenuId: number | null = null;

  isSelected(id: number): boolean { return this.selectedIds.has(id); }
  toggle(record: BillingRecord): void {
    const next = new Set(this.selectedIds);
    next.has(record.id) ? next.delete(record.id) : next.add(record.id);
    this.selectedIdsChange.emit(next);
  }
  toggleAll(): void {
    const next = new Set(this.selectedIds);
    const allSelected = this.records.length > 0 && this.records.every(r => next.has(r.id));
    this.records.forEach(r => allSelected ? next.delete(r.id) : next.add(r.id));
    this.selectedIdsChange.emit(next);
  }
  allSelected(): boolean { return this.records.length > 0 && this.records.every(r => this.selectedIds.has(r.id)); }
  someSelected(): boolean { return this.records.some(r => this.selectedIds.has(r.id)) && !this.allSelected(); }
  emitAction(type: string, record: BillingRecord): void {
    this.openMenuId = null;
    this.action.emit({ type, record });
  }

  toggleMenu(record: BillingRecord, event: MouseEvent): void {
    event.stopPropagation();
    this.openMenuId = this.openMenuId === record.id ? null : record.id;
  }

  onUploadCsv(record: BillingRecord, event: Event): void {
    const input = event.target as HTMLInputElement;
    this.openMenuId = null;
    if (input.files && input.files.length > 0) {
      this.action.emit({ type: 'upload-csv', record });
      input.value = '';
    }
  }

  money(value: number): string { return value.toFixed(2); }
}
<div class="table-scroll">
<table>
  <thead>
    <tr>
      <th class="check"><input type="checkbox" [checked]="allSelected()" [indeterminate]="someSelected()" (change)="toggleAll()" aria-label="Select all"></th>
      <th>Order Details</th><th>Reseller Details</th><th>Invoice ID</th><th>Cs</th><th>Country</th><th>Fx</th><th>Total VC</th><th>Total RP</th><th>Actions</th>
    </tr>
  </thead>
  <tbody>
    <tr *ngFor="let row of records">
      <td class="check"><input type="checkbox" [checked]="isSelected(row.id)" (change)="toggle(row)" [attr.aria-label]="'Select ' + row.orderNumber"></td>
      <td class="order-cell"><strong>{{ row.orderNumber }}</strong><span class="date">{{ row.orderDate | date:'dd MMM, yyyy' }} &nbsp; {{ row.orderTime }}</span></td>
      <td class="reseller"><strong>{{ row.reseller }}</strong><span>{{ row.resellerId }}</span></td>
      <td>{{ row.invoiceId }}</td>
      <td><span class="erp">ERP</span> {{ row.customerType }}</td>
      <td>{{ row.country }}</td><td>{{ row.currency }}</td>
      <td>{{ money(row.totalVc) }}</td><td>{{ money(row.totalRp) }}</td>
      <td class="actions">
        <button title="Delete" (click)="emitAction('delete', row)">
          <img src="../../../assets/images/red-close.svg">
        </button>
        <button title="Approve" (click)="emitAction('approve', row)">
          <img src="../../../assets/images/green-tick.svg">
        </button>
        <div class="more-wrap">
          <button class="more" title="More actions" (click)="toggleMenu(row, $event)">•••</button>
          <div class="more-menu" *ngIf="openMenuId === row.id" (click)="$event.stopPropagation()">
            <button type="button" (click)="emitAction('delete', row)"><span class="menu-icon">
              <img src="../../../assets/images/green-tick.svg">
            </span>Delete</button>
            <label class="menu-upload"><span class="menu-icon">⇧</span>Upload CSV<input type="file" accept=".csv,text/csv" (change)="onUploadCsv(row, $event)"></label>
          </div>
        </div>
      </td>
    </tr>
    <tr *ngIf="records.length === 0"><td colspan="10" class="empty">No billing records found for the selected criteria.</td></tr>
  </tbody>
</table>
</div>
